toolArgs.file_text:
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #b5bac1;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.25rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

.channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #f23f43;
    color: #fff;
    border-radius: 10px;
    padding: 0 6px;
    font-size: 0.7rem;
    font-weight: 700;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.thread-open {
    max-width: 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #313338;
    color: #f2f3f5;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

.message-area-header .channel-desc {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #949ba4;
    font-size: 0.85rem;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #949ba4;
    background: #313338;
}

/* Message Bubble */
.message-bubble {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

.message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

.message-content {
    margin-top: 0.25rem;
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dbdee1;
}

.message-reactions {
    display: flex;
    gap: 0.25rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #f2f3f5;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #404249;
}

.thread-link {
    background: none;
    border: none;
    color: #00a8fc;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px;
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 3px;
    font-size: 0.9rem;
    transition: background 0.1s;
}

.action-btn:hover {
    background: #404249;
}

.emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 6px;
    padding: 4px;
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    font-size: 1.1rem;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #404249;
}

/* Message Input */
.message-input-area {
    display: flex;
    align-items: flex-end;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #3f4147;
    background: #383a40;
}

.message-textarea {
    flex: 1;
    resize: none;
    border: none;
    border-radius: 8px;
    padding: 0.6rem 1rem;
    font-size: 0.9rem;
    background: #2b2d31;
    color: #f2f3f5;
    outline: none;
    min-height: 2.5rem;
    max-height: 8rem;
    font-family: inherit;
}

.message-textarea::placeholder {
    color: #6d6f78;
}

.send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 0.6rem 1.2rem;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #4752c4;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    color: #f2f3f5;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.15s;
}

.close-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

